recommendation:
Restructure removeLiquidityImbalanced to follow CEI pattern: (1) Calculate lpAmountIn first using current reserves minus requested amounts, (2) Burn LP tokens from msg.sender, (3) Then transfer tokens out. Code fix:

function removeLiquidityImbalanced(...) external nonReentrant expire(deadline) returns (uint256 lpAmountIn) {
    IERC20[] memory _tokens = tokens();
    uint256 tokensLength = _tokens.length;
    uint256[] memory reserves = _updatePumps(tokensLength);

    // CHECKS & EFFECTS first
    uint256[] memory newReserves = new uint256[](tokensLength);
    for (uint256 i; i < tokensLength; ++i) {
        newReserves[i] = reserves[i] - tokenAmountsOut[i];
    }
    lpAmountIn = totalSupply() - _calcLpTokenSupply(wellFunction(), newReserves);
    if (lpAmountIn > maxLpAmountIn) revert SlippageIn(lpAmountIn, maxLpAmountIn);
    _burn(msg.sender, lpAmountIn);
    _setReserves(_tokens, newReserves);

    // INTERACTIONS last
    for (uint256 i; i < tokensLength; ++i) {
        _tokens[i].safeTransfer(recipient, tokenAmountsOut[i]);
    }
    emit RemoveLiquidity(lpAmountIn, tokenAmountsOut, recipient);
}

Add explicit uint128 bounds checking in `_setReserves`:

function _setReserves(IERC20[] memory _tokens, uint256[] memory reserves) internal {
    for (uint256 i; i < reserves.length; ++i) {
        if (reserves[i] > _tokens[i].balanceOf(address(this))) revert InvalidReserves();
        if (reserves[i] > type(uint128).max) revert ReserveOverflow(i, reserves[i]);
    }
    LibBytes.storeUint128(RESERVES_STORAGE_SLOT, reserves);
}

